        u=f"https://api.bybit.com/v5/market/kline?category=linear&symbol={sym}&interval=1&start={start*1000}&limit=1000"
        for k in json.load(urllib.request.urlopen(u,timeout=20))["result"]["list"]:
            t=int(k[0])//1000
            if T0<=t<T0+86400: out[(t-T0)//60]=float(k[4])
    return out
for path,sym in [("ethereum/ETH","ETHUSDT"),("ethereum/LINK","LINKUSDT"),("bsc-core/IRYS","IRYSUSDT"),("base/MORPHO","MORPHOUSDT")]:
    m,n,a,b,g=dex_minutes(f"/data/tk0364/outw/{path}/{DAY}.csv")
    by=bybit(sym)
    ks=sorted(set(m)&set(by)); 
    # forward-fill dex
    pairs=[]; last=None; mk=sorted(m)
    for k in range(1440):
        if k in m: last=m[k]
        if last and k in by: pairs.append((last,by[k]))
    rd=[math.log(pairs[i][0]/pairs[i-1][0]) for i in range(1,len(pairs))]
    rb=[math.log(pairs[i][1]/pairs[i-1][1]) for i in range(1,len(pairs))]
    def corr(x,y):
        mx,my=st.mean(x),st.mean(y); sx=math.sqrt(sum((a-mx)**2 for a in x)); sy=math.sqrt(sum((b-my)**2 for b in y))
        return sum((a-mx)*(b-my) for a,b in zip(x,y))/(sx*sy) if sx and sy else float("nan")
    c=corr(rd,rb)
    # range comparison (scale-free): dex price range ratio vs bybit
    dr=max(p for p,_ in pairs)/min(p for p,_ in pairs); br=max(q for _,q in pairs)/min(q for _,q in pairs)
    print(f"{path:16} swaps={n:6} minutes_with_swap={len(m):4} first={a and (a-T0)//60} last={b and (b-T0)//60} gaps>10m={g} corr1m={c:+.3f} range_dex={dr:.4f} range_bybit={br:.4f}")
EOF
